def seed_categories(apps, schema_editor):
    """Fresh databases get the default lists. A database that already has
    categories keeps its own curated list (seeding by name would create
    near-duplicates like "arroz" next to "arroces"); it only gets the
    "otros" fallback. Either way, anything without a category moves to
    "otros", since the columns become NOT NULL right after this."""
